package com.mukasanches.zapptv.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class ChannelResolverTest {
    @Test
    fun resolvesCommonBrazilianNames() {
        assertEquals("BR_GLOBO", ChannelResolver.canonicalId("Globo HD"))
        assertEquals("BR_SBT", ChannelResolver.canonicalId("SBT 5.1"))
        assertEquals("BR_TV_CULTURA", ChannelResolver.canonicalId("TV Cultura HD"))
        assertEquals("BR_TV_CAMARA", ChannelResolver.canonicalId("TV Câmara"))
    }

    @Test
    fun normalizationRemovesAccentsAndPunctuation() {
        assertEquals("tv camara hd", ChannelResolver.normalize("TV CÂMARA — HD"))
    }

    @Test
    fun unknownChannelRemainsUnmapped() {
        assertNull(ChannelResolver.canonicalId("Canal local desconhecido"))
    }
}

